   142	        /// <summary>Butchers `n` generated adults of `kindDefName` at efficiency 1 under a fixed Rand seed (so two kinds of equal
   143	        /// mass round alike) through the real Pawn.ButcherProducts, so the yield-curve prefix runs. Returns summed meat/leather and
   144	        /// the kernel factor the curve should apply (1 when the tier is not T1/T2 or the curve is off).</summary>
   145	        public static string ButcherYieldReport(string kindDefName)
   146	        {
   147	            PawnKindDef kind = DefDatabase<PawnKindDef>.GetNamedSilentFail(kindDefName);
   148	            if (kind == null) return "FAIL no kind " + kindDefName;
   149	            const int n = 6;
   150	            int meat = 0, leather = 0;
   151	            float factor = 1f;
   152	            TitanicTier tier = TitanicTier.None;
   153	            for (int i = 0; i < n; i++)
   154	            {
   155	                Pawn p = MakeAdult(kind, Find.CurrentMap);
   156	                tier = TitanicTierUtility.GetTier(p);
   157	                if (RM_HugeThingsSettings.YieldCurveActive && (tier == TitanicTier.T1 || tier == TitanicTier.T2))
   158	                    factor = YieldCurveUtility.SubLinearFactor(p, tier);
   159	                Rand.PushState(424242 + i);
   160	                try
   161	                {
   162	                    foreach (Thing t in p.ButcherProducts(null, 1f))
   163	                    {
   164	                        if (t.def == p.RaceProps.meatDef) meat += t.stackCount;
   165	                        else if (t.def == p.RaceProps.leatherDef) leather += t.stackCount;
   166	                    }
   167	                }
   168	                catch (System.Exception ex)
   169	                {
   170	                    return "FAIL ButcherProducts threw " + ex.GetType().Name + ": " + ex.Message;
   171	                }
   172	                finally
   173	                {
   174	                    Rand.PopState();
   175	                }
   176	                p.Destroy();
   177	            }
   178	            return kind.defName + " tier=" + tier + " n=" + n + " meat=" + meat + " leather=" + leather + " factor=" + factor.ToString("0.0000");
   179	        }
