   181	        /// <summary>T2 wake on a thin roof and a wall: puts RoofConstructed and a wood wall on the cell east of `cell`, spawns an adult
   182	        /// of `kindDefName` at `cell` and moves it east through the real Thing.Position setter (the wake's trigger), then reads the
   183	        /// roof and the wall back. Cleans up the pawn, the wall and the roof.</summary>
   184	        public static string RoofWallProbe(string kindDefName, IntVec3 cell)
   185	        {
   186	            Map map = Find.CurrentMap;
   187	            PawnKindDef kind = DefDatabase<PawnKindDef>.GetNamedSilentFail(kindDefName);
   188	            if (map == null || kind == null) return "FAIL no map or kind " + kindDefName;
   189	            IntVec3 east = cell + IntVec3.East;
   190	            if (!cell.InBounds(map) || !east.InBounds(map) || !cell.Walkable(map)) return "FAIL cell not usable " + cell;
   191	            map.roofGrid.SetRoof(east, RoofDefOf.RoofConstructed);
   192	            Thing wall = GenSpawn.Spawn(ThingMaker.MakeThing(ThingDefOf.Wall, ThingDefOf.WoodLog), east, map);
