   208	        // Pawn_PathFollower.CostToMoveIntoCell(Pawn, IntVec3) is private static: the exact overload Patch_ThickRoofAvoidance targets.
   209	        private static readonly System.Reflection.MethodInfo CostMethod = HarmonyLib.AccessTools.Method(typeof(Verse.AI.Pawn_PathFollower),
   210	            "CostToMoveIntoCell", new[] { typeof(Pawn), typeof(IntVec3) });
