   217	        /// <summary>Thick-roof slow-down: the step cost (Verse.AI.Pawn_PathFollower.CostToMoveIntoCell, which Patch_ThickRoofAvoidance
   218	        /// postfixes) into the cell east of `cell`, open and then under RoofRockThick, for a spawned adult of `kindDefName`. The
   219	        /// cell's original roof is put back.</summary>
   220	        public static string ThickRoofCostProbe(string kindDefName, IntVec3 cell)
   221	        {
