   223	            PawnKindDef kind = DefDatabase<PawnKindDef>.GetNamedSilentFail(kindDefName);
   224	            if (map == null || kind == null) return "FAIL no map or kind " + kindDefName;
   225	            if (CostMethod == null) return "FAIL Pawn_PathFollower.CostToMoveIntoCell(Pawn, IntVec3) not found";
   226	            IntVec3 east = cell + IntVec3.East;
   227	            if (!cell.InBounds(map) || !east.InBounds(map) || !east.Walkable(map)) return "FAIL cell not usable " + cell;
   228	            RoofDef orig = east.GetRoof(map);
   229	            Pawn p = MakeAdult(kind, map);
   230	            GenSpawn.Spawn(p, cell, map);
