   232	            map.roofGrid.SetRoof(east, null);
   233	            float open = StepCost(p, east);
   234	            map.roofGrid.SetRoof(east, RoofDefOf.RoofRockThick);
   235	            float thick = StepCost(p, east);
   236	            map.roofGrid.SetRoof(east, orig);
   237	            p.Destroy();
   238	            return kind.defName + " tier=" + tier + " costOpen=" + open.ToString("0.0") + " costThick=" + thick.ToString("0.0");
   239	        }
