    24	        public static void ProcessFootprint(Pawn titan, TitanicTier tier)
    25	        {
    26	            // MOD_OPTIONS_RETROFIT_1: master switch for the whole wake.
    27	            if (!RM_HugeThingsSettings.WakeActive) return;
    28	
    29	            if (titan.Flying) return; // TITAN_WAKE_FIXES_1 (B3.8): no ground wake while airborne
    30	            Map map = titan.Map;
    31	            CellRect rect = titan.OccupiedRect();
    32	            // TITAN_WAKE_FIXES_1 (B3.6): 1.6 ThingGrid registers a multi-cell thing in every cell it covers, so crushables are gathered
    33	            // across the whole footprint first and each is struck once per step (a 2x2 under a 4x4 step took four blows before).
    34	            var cells = new List<List<Thing>>();
    35	            foreach (IntVec3 c in rect)
    36	            {
    37	                if (!c.InBounds(map))
    38	                {
    39	                    continue;
