    44	                    FilthMaker.TryMakeFilth(c, map, ThingDefOf.Filth_RubbleRock);
    45	                }
    46	                cells.Add(c.GetThingList(map).ToList()); // copy: destroying below mutates the live lists
    47	            }
    48	            foreach (Thing t in RM_TitanicKernel.UniqueInOrder<Thing>(cells))
    49	            {
    50	                ProcessCrushable(t, tier, titan);
